<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';import {ref} from 'vue';import PageHeader from '@/Components/Shared/PageHeader.vue';import Pagination from '@/Components/Shared/Pagination.vue';import StatusBadge from '@/Components/Shared/StatusBadge.vue';import {Button} from '@/components/ui/button';const p=defineProps<{tickets:any;filters:any;statuses:string[];priorities:string[];categories:any[]}>();const search=ref(p.filters.search??''),status=ref(p.filters.status??''),priority=ref(p.filters.priority??''),category_id=ref(p.filters.category_id??''),assignee=ref(p.filters.assignee??'');function apply(){router.get('/admin/support/tickets',{search:search.value||undefined,status:status.value||undefined,priority:priority.value||undefined,category_id:category_id.value||undefined,assignee:assignee.value||undefined},{preserveState:true,replace:true})}</script><template><Head title="Support Tickets"/><div class="space-y-6 p-6"><PageHeader title="Support Tickets" description="Search, triage, assign, and manage customer support requests."/><div class="grid gap-3 rounded-lg border bg-card p-4 md:grid-cols-6"><input v-model="search" class="h-10 rounded-md border bg-background px-3 md:col-span-2" placeholder="Ticket, subject, customer..."/><select v-model="status" class="h-10 rounded-md border bg-background px-3"><option value="">All statuses</option><option v-for="x in statuses" :value="x">{{x}}</option></select><select v-model="priority" class="h-10 rounded-md border bg-background px-3"><option value="">All priorities</option><option v-for="x in priorities" :value="x">{{x}}</option></select><select v-model="category_id" class="h-10 rounded-md border bg-background px-3"><option value="">All categories</option><option v-for="x in categories" :value="x.id">{{x.name}}</option></select><select v-model="assignee" class="h-10 rounded-md border bg-background px-3"><option value="">All assignees</option><option value="mine">My tickets</option><option value="unassigned">Unassigned</option></select><Button @click="apply">Apply</Button></div><div class="overflow-x-auto rounded-lg border"><table class="w-full min-w-[1000px] text-sm"><thead class="bg-muted/40"><tr><th class="p-3 text-left">Ticket</th><th class="p-3 text-left">Customer</th><th class="p-3 text-left">Status</th><th class="p-3 text-left">Priority</th><th class="p-3 text-left">Category</th><th class="p-3 text-left">Assignee</th><th class="p-3 text-left">Updated</th></tr></thead><tbody class="divide-y"><tr v-for="t in tickets.data" :key="t.uuid"><td class="p-3"><Link class="font-medium hover:underline" :href="`/admin/support/tickets/${t.uuid}`">{{t.ticket_number}}</Link><p class="text-muted-foreground">{{t.subject}}</p></td><td class="p-3">{{t.customer}}<p class="text-muted-foreground">{{t.customer_email}}</p></td><td class="p-3"><StatusBadge :status="t.status"/></td><td class="p-3"><StatusBadge :status="t.priority"/></td><td class="p-3">{{t.category||'—'}}</td><td class="p-3">{{t.assignee||'Unassigned'}}</td><td class="p-3">{{t.updated_at}}</td></tr><tr v-if="!tickets.data.length"><td colspan="7" class="p-8 text-center text-muted-foreground">No tickets found.</td></tr></tbody></table></div><Pagination :links="tickets.links" :from="tickets.from" :to="tickets.to" :total="tickets.total" item-label="tickets" show-summary/></div></template>